//! `ProcessSubmitterCompletionJob`: after a submitter completes the form, record the
//! completion, invite the next parties of an ordered submission, and send the
//! `form.completed` and `submission.completed` webhooks.
//!
//! Result documents, the audit trail and the completed emails (which attach them) are
//! generated by later steps of Phase 4; until then the job skips them.

use std::collections::HashMap;

use loco_db::{
    signing::{self, NewCompletedSubmitter},
    submissions::{self, Submitter},
};
use loco_jobs::{EnqueueOptions, Job};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use super::Form;
use crate::{
    errors::AppError,
    state::AppState,
    webhooks::{self, EventRecord},
};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ProcessSubmitterCompletion {
    pub submitter_id: i64,
    #[serde(default)]
    pub is_last: Option<bool>,
    #[serde(default)]
    pub send_invitation_email: Option<bool>,
}

impl Job for ProcessSubmitterCompletion {
    const KIND: &'static str = "process_submitter_completion";

    type Context = AppState;

    async fn run(self, state: AppState) -> anyhow::Result<()> {
        process(&state, &self).await.map_err(AppError::into_anyhow)
    }
}

/// `ProcessSubmitterCompletionJob.perform_async`.
pub async fn enqueue(
    state: &AppState,
    submitter_id: i64,
    is_last: Option<bool>,
) -> anyhow::Result<()> {
    loco_jobs::enqueue(
        &state.db,
        &ProcessSubmitterCompletion {
            submitter_id,
            is_last,
            send_invitation_email: None,
        },
        EnqueueOptions::default(),
    )
    .await?;
    Ok(())
}

async fn process(state: &AppState, job: &ProcessSubmitterCompletion) -> Result<(), AppError> {
    let Some(submitter) = submissions::find_submitter(&state.db, job.submitter_id).await? else {
        return Err(anyhow::anyhow!("submitter {} not found", job.submitter_id).into());
    };
    let form = Form::for_submitter(state, submitter).await?;

    create_completed_submitter(state, &form).await?;

    let is_last = if let Some(is_last) = job.is_last {
        is_last
    } else {
        let viewers: Vec<&str> = form
            .template_submitters()
            .iter()
            .filter(|s| loco_domain::submit::present(s.get("is_viewer")))
            .filter_map(|s| s.get("uuid").and_then(Value::as_str))
            .collect();
        let incomplete = form
            .submitters
            .iter()
            .any(|s| s.completed_at.is_none() && !viewers.contains(&s.uuid.as_str()));
        let max = form.submitters.iter().filter_map(|s| s.completed_at).max();
        !incomplete && form.submitter.completed_at == max
    };

    create_completed_documents(state, &form.submitter).await?;

    let submission = submissions::find(&state.db, form.submission.id).await?;
    if submission
        .as_ref()
        .is_some_and(|s| s.completed_at.is_none())
        && form.submission.submitters_order == "preserved"
        && job.send_invitation_email != Some(false)
    {
        let next = next_submitters(&form);
        let refs: Vec<&Submitter> = next.iter().collect();
        crate::api::create::send_signature_requests(state, &refs).await;
        if !is_last {
            let viewers = next_viewers(&form, &next);
            let refs: Vec<&Submitter> = viewers.iter().collect();
            crate::api::create::send_signature_requests(state, &refs).await;
        }
    }

    let record = |id| EventRecord {
        id,
        account_id: form.submitter.account_id,
    };
    webhooks::enqueue(state, "form.completed", &[record(form.submitter.id)]).await;
    if is_last {
        webhooks::enqueue(state, "submission.completed", &[record(form.submission.id)]).await;
    }
    Ok(())
}

/// `create_completed_submitter!`.
async fn create_completed_submitter(state: &AppState, form: &Form) -> Result<(), AppError> {
    let Some(completed_at) = form.submitter.completed_at else {
        return Ok(());
    };
    let events = signing::events_of_types(
        &state.db,
        form.submitter.id,
        &[
            "send_sms",
            "send_2fa_sms",
            "complete_verification",
            "complete_kba",
        ],
    )
    .await?;
    let (verifications, sms): (Vec<_>, Vec<_>) = events
        .into_iter()
        .partition(|(t, _)| t == "complete_verification" || t == "complete_kba");
    let verification_method = verifications.first().and_then(|(t, data)| {
        if t == "complete_kba" {
            Some("kba".to_owned())
        } else {
            data.get("method")
                .and_then(Value::as_str)
                .map(str::to_owned)
        }
    });
    let sms_count: i64 = sms
        .iter()
        .map(|(_, data)| data.get("segments").and_then(Value::as_i64).unwrap_or(1))
        .sum();
    signing::create_completed_submitter(
        &state.db,
        &NewCompletedSubmitter {
            submitter_id: form.submitter.id,
            submission_id: form.submission.id,
            account_id: form.submission.account_id,
            template_id: form.submission.template_id,
            source: &form.submission.source,
            sms_count: i32::try_from(sms_count).unwrap_or(i32::MAX),
            verification_method: verification_method.as_deref(),
            completed_at,
        },
    )
    .await?;
    Ok(())
}

/// `create_completed_documents!`: one row per result document with a checksum.
async fn create_completed_documents(
    state: &AppState,
    submitter: &Submitter,
) -> Result<(), AppError> {
    let documents = loco_storage::Attachment::with_blobs_for_records(
        &state.db,
        "Submitter",
        &[submitter.id],
        "documents",
    )
    .await?;
    for (_, blob) in documents {
        // `attachment.metadata` is the blob's.
        let metadata = blob.metadata_json();
        if let Some(sha256) = metadata
            .get("sha256")
            .and_then(Value::as_str)
            .filter(|s| !s.is_empty())
        {
            signing::create_completed_document(&state.db, submitter.id, sha256).await?;
        }
    }
    Ok(())
}

/// `enqueue_next_submitter_request_notification`: the next order group once the current
/// one has completed, or the first party not yet completed or sent.
fn next_submitters(form: &Form) -> Vec<Submitter> {
    let index: HashMap<&str, &Submitter> = form
        .submitters
        .iter()
        .filter(|s| !form.is_viewer(s))
        .map(|s| (s.uuid.as_str(), s))
        .collect();
    let items = form.template_submitters();
    let uuid = |item: &Value| uuid(item).to_owned();
    let next: Vec<String> = if items
        .iter()
        .any(|s| s.get("order").is_some_and(|o| !o.is_null()))
    {
        let groups = order_groups(items);
        let current = groups.iter().position(|g| {
            g.iter()
                .any(|s| s.get("uuid").and_then(Value::as_str) == Some(&form.submitter.uuid))
        });
        match current {
            Some(i)
                if groups.get(i + 1).is_some()
                    && groups[i]
                        .iter()
                        .filter_map(|s| index.get(uuid(s).as_str()))
                        .all(|s| s.completed_at.is_some()) =>
            {
                groups[i + 1].iter().map(|s| uuid(s)).collect()
            }
            _ => Vec::new(),
        }
    } else {
        items
            .iter()
            .find(|e| {
                index
                    .get(uuid(e).as_str())
                    .is_some_and(|s| s.completed_at.is_none() && s.sent_at.is_none())
            })
            .map(|e| vec![uuid(e)])
            .unwrap_or_default()
    };
    next.iter()
        .filter_map(|u| index.get(u.as_str()).map(|s| (*s).clone()))
        .collect()
}

/// `group_by.with_index { |s, i| s['order'] || i }.sort_by(&:first)`.
fn order_groups(items: &[Value]) -> Vec<Vec<&Value>> {
    let mut groups: Vec<(i64, Vec<&Value>)> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let key = item
            .get("order")
            .and_then(Value::as_i64)
            .unwrap_or(i64::try_from(index).unwrap_or_default());
        match groups.iter_mut().find(|(k, _)| *k == key) {
            Some((_, group)) => group.push(item),
            None => groups.push((key, vec![item])),
        }
    }
    groups.sort_by_key(|(k, _)| *k);
    groups.into_iter().map(|(_, g)| g).collect()
}

fn uuid(item: &Value) -> &str {
    item.get("uuid").and_then(Value::as_str).unwrap_or_default()
}

/// `enqueue_next_submitter_viewer_notification`: viewers in the next parties' order
/// group, or right after the next party.
fn next_viewers(form: &Form, next: &[Submitter]) -> Vec<Submitter> {
    let viewers: HashMap<&str, &Submitter> = form
        .submitters
        .iter()
        .filter(|s| form.is_viewer(s))
        .map(|s| (s.uuid.as_str(), s))
        .collect();
    if viewers.is_empty() {
        return Vec::new();
    }
    let next_uuids: Vec<&str> = next.iter().map(|s| s.uuid.as_str()).collect();
    let items = form.template_submitters();
    if items
        .iter()
        .any(|s| s.get("order").is_some_and(|o| !o.is_null()))
    {
        let orders: Vec<&Value> = items
            .iter()
            .filter(|s| next_uuids.contains(&uuid(s)))
            .map(|s| s.get("order").unwrap_or(&Value::Null))
            .collect();
        items
            .iter()
            .filter(|s| orders.contains(&s.get("order").unwrap_or(&Value::Null)))
            .filter_map(|s| viewers.get(uuid(s)).map(|v| (*v).clone()))
            .collect()
    } else {
        let mut preceding: Option<&str> = None;
        let mut out = Vec::new();
        for item in items {
            if let Some(viewer) = viewers.get(uuid(item)) {
                if preceding.is_some_and(|p| next_uuids.contains(&p)) {
                    out.push((*viewer).clone());
                }
            } else {
                preceding = Some(uuid(item));
            }
        }
        out
    }
}
